const std = @import("std");

const Pair = struct { left: []const u8, right: []const u8 };
const PairCtx = struct {
    pub fn hash(_: @This(), p: Pair) u64 {
        return std.hash.Wyhash.hash(0, p.left);
    }
    pub fn eql(_: @This(), a: Pair, b: Pair) bool {
        return std.mem.eql(u8, a.left, b.left) and std.mem.eql(u8, a.right, b.right);
    }
};

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const alloc = gpa.allocator();

    var list = std.ArrayList(u32).empty;
    defer list.deinit(alloc);
    try list.append(alloc, 1);
    try list.appendSlice(alloc, &[_]u32{ 2, 3 });

    var m = std.StringHashMap(i32).init(alloc);
    defer m.deinit();
    try m.put("a", 1);

    var m2 = std.StringHashMapUnmanaged(i32){};
    defer m2.deinit(alloc);
    try m2.put(alloc, "b", 2);

    var m3 = std.HashMapUnmanaged(Pair, u32, PairCtx, std.hash_map.default_max_load_percentage){};
    defer m3.deinit(alloc);
    try m3.put(alloc, .{ .left = "x", .right = "y" }, 5);

    var arena = std.heap.ArenaAllocator.init(alloc);
    defer arena.deinit();
    const a = arena.allocator();

    var buf = std.ArrayList(u8).empty;
    defer buf.deinit(a);
    try buf.appendSlice(a, "hi");
    const owned = try buf.toOwnedSlice(a);

    const args = try std.process.argsAlloc(alloc);
    defer std.process.argsFree(alloc, args);

    std.debug.print("{s} {d} {s}\n", .{ owned, list.items.len, args[0] });
}

