fn heapPop(self: *State) HeapEntry {
    const items = self.heap.items;
    const top = items[0];
    const last = items[items.len - 1];
    self.heap.items.len -= 1;
    if (self.heap.items.len == 0) return top;
    items[0] = last;
    // sift down
    var i: usize = 0;
    const n = self.heap.items.len;
    while (true) {
        var c = 2*i+1;
        if (c >= n) break;
        if (c+1 < n and less(items[c+1], items[c])) c += 1;
        if (!less(items[c], items[i])) break;
        std.mem.swap(...);
        i = c;
    }
    return top;
}
```
