const std = @import("std");
const tokmod = @import("tokenizer.zig");

const Vector = struct { text: []const u8, ids: []i32 };

fn readAll(io: std.Io, alloc: std.mem.Allocator, path: []const u8) ![]u8 {
    const dir = std.Io.Dir.cwd();
    const lim: std.Io.Limit = @enumFromInt(1 << 30);
    return try dir.readFileAlloc(io, path, alloc, lim);
}

fn hexDecode(alloc: std.mem.Allocator, s: []const u8) ![]u8 {
    const out = try alloc.alloc(u8, s.len / 2);
    _ = try std.fmt.hexToBytes(out, s);
    return out;
}

fn loadHexLines(io: std.Io, alloc: std.mem.Allocator, path: []const u8) ![]const []const u8 {
    const data = try readAll(io, alloc, path);
    var list = std.ArrayList([]const u8).empty;
    var it = std.mem.splitScalar(u8, data, '\n');
    while (it.next()) |line| {
        if (line.len == 0) continue;
        try list.append(alloc, try hexDecode(alloc, line));
    }
    return try list.toOwnedSlice(alloc);
}

fn loadTypes(io: std.Io, alloc: std.mem.Allocator, path: []const u8) ![]const u32 {
    const data = try readAll(io, alloc, path);
    var list = std.ArrayList(u32).empty;
    var it = std.mem.splitScalar(u8, data, '\n');
    while (it.next()) |line| {
        if (line.len == 0) continue;
        try list.append(alloc, try std.fmt.parseInt(u32, line, 10));
    }
    return try list.toOwnedSlice(alloc);
}

pub fn main() !void {
    var arena_state = std.heap.ArenaAllocator.init(std.heap.page_allocator);
    defer arena_state.deinit();
    const alloc = arena_state.allocator();

    var threaded = std.Io.Threaded.init(std.heap.page_allocator, .{});
    const io = threaded.io();

    const tokens = try loadHexLines(io, alloc, "/workspace/tools/tokdata/tokens.hex");
    const merges = try loadHexLines(io, alloc, "/workspace/tools/tokdata/merges.hex");
    const types = try loadTypes(io, alloc, "/workspace/tools/tokdata/types.txt");

    var tk = try tokmod.Tokenizer.init(alloc, tokens, types, merges, 248044, 248046, false);
    defer tk.deinit();

    // ---- visible JSON vectors ----
    const vdata = try readAll(io, alloc, "/workspace/TOKENIZER-VECTORS.json");
    const parsed = try std.json.parseFromSlice([]Vector, alloc, vdata, .{ .ignore_unknown_fields = true });
    var pass: usize = 0;
    var fail: usize = 0;
    for (parsed.value) |v| {
        const got = try tk.tokenize(alloc, v.text, false);
        var ok = got.len == v.ids.len;
        if (ok) {
            for (got, v.ids) |g, e| {
                if (g != e) {
                    ok = false;
                    break;
                }
            }
        }
        if (ok) {
            pass += 1;
        } else {
            fail += 1;
            std.debug.print("FAILVEC text={s}\n  got=", .{v.text});
            for (got) |g| std.debug.print("{d} ", .{g});
            std.debug.print("\n  exp=", .{});
            for (v.ids) |e| std.debug.print("{d} ", .{e});
            std.debug.print("\n", .{});
        }
    }
    std.debug.print("VECTORS pass={d} fail={d}\n", .{ pass, fail });

    // ---- corpus timing (wall time measured externally) ----
    const corpus = try readAll(io, alloc, "/workspace/data/samples/corpus.txt");
    const cids = try tk.tokenize(alloc, corpus, false);
    std.debug.print("CORPUS bytes={d} ids={d}\n", .{ corpus.len, cids.len });

    // ---- optional batch: one hex text per line ----
    if (readAll(io, alloc, "/workspace/tools/tokdata/testhex.txt")) |bdata| {
        var it = std.mem.splitScalar(u8, bdata, '\n');
        while (it.next()) |line| {
            if (line.len == 0) continue;
            const text = try hexDecode(alloc, line);
            const ids = try tk.tokenize(alloc, text, false);
            std.debug.print("BATCH ok {d}", .{ids.len});
            for (ids) |id| std.debug.print(" {d}", .{id});
            std.debug.print("\n", .{});
        }
    } else |_| {}
}

