    var idx: usize = 0;
    inline for (0..5) |dg| {
        inline for (0..16) |j| {
            const v: u8 = blk[j] *% @as(u8, pow3[dg]);
            const q: i32 = @as(i32, (@as(u16, v) * 3) >> 8) - 1;
            out[idx] = d * @as(f32, @floatFromInt(q));
            idx += 1;
        }
    }
    inline for (0..5) |dg| {
        inline for (0..8) |j| {
            const v: u8 = blk[16 + j] *% @as(u8, pow3[dg]);
            const q: i32 = @as(i32, (@as(u16, v) * 3) >> 8) - 1;
