pub const Error = error{ BadGguf, OutOfMemory };

pub fn parse(alloc: std.mem.Allocator, data: []const u8) Error!*Gguf {
    const g = try alloc.create(Gguf);
    g.* = .{ .alloc = alloc, .data = data, .tensors = &.{}, .data_offset = 0 };
